/**
 * `@huaqiu/component-gen-app` — completed-generation result stage.
 *
 * Renders the preview (from `ports.artifactContent`), a download action and a
 * note when the generation was auto-generated or degraded. DSH-agnostic.
 */
import { useCallback, useEffect, useState, type ReactElement, type ReactNode } from 'react'
import type { ComponentGenPorts } from '../ports.js'
import type { Translate } from '../copy/index.js'
import { triggerDownload } from '../utils/ecad.js'
import { PreviewStage } from './PreviewStage.js'
import { SourceImage } from './SourceImage.js'

export interface ResultStageProps {
  ports: ComponentGenPorts
  kind: 'symbol' | 'footprint'
  result: Record<string, unknown>
  t: Translate
  /** bump to force a re-render of the preview for a new result. */
  srcKey: string
  /** optional action rendered on the left of the top bar. */
  leading?: ReactNode
  /** 用户上传的原始图片（含历史记录重新打开时恢复的图片）。 */
  sourceImage?: string | null
}

function artifactIdOf(result: Record<string, unknown>): string | null {
  const art = result.artifact
  if (art && typeof art === 'object') {
    const id = (art as { id?: unknown }).id
    if (typeof id === 'string' && id) return id
  }
  return null
}

/**
 * HQ Edge-resolvable URI of the generated artifact (`file://`), attached by
 * the node half when the placement channel is available. Place stays hidden
 * when it is missing.
 */
function artifactUriOf(result: Record<string, unknown>): string | null {
  const art = result.artifact
  if (art && typeof art === 'object') {
    const uri = (art as { uri?: unknown }).uri
    if (typeof uri === 'string' && uri) return uri
  }
  return null
}

function filenameOf(result: Record<string, unknown>, kind: string): string {
  const f = result.filename
  if (typeof f === 'string' && f) return f
  return `generated.${kind === 'symbol' ? 'kicad_sym' : 'kicad_mod'}`
}

export function ResultStage({ ports, kind, result, t, srcKey, leading, sourceImage }: ResultStageProps): ReactElement {
  const artifactId = artifactIdOf(result)
  const artifactUri = artifactUriOf(result)
  const [content, setContent] = useState<string | null>(null)
  const [previewErr, setPreviewErr] = useState<string | null>(null)
  const [downloading, setDownloading] = useState(false)
  const [placing, setPlacing] = useState(false)
  const [placeStatus, setPlaceStatus] = useState<string | null>(null)

  useEffect(() => {
    if (!artifactId) return
    let cancelled = false
    setContent(null)
    setPreviewErr(null)
    ports.artifactContent(artifactId)
      .then((text) => { if (!cancelled) setContent(text) })
      .catch((e) => { if (!cancelled) setPreviewErr(String((e as Error)?.message || e)) })
    return () => { cancelled = true }
  }, [artifactId, ports, srcKey])

  const download = useCallback(async (): Promise<void> => {
    setDownloading(true)
    try {
      if (artifactId) {
        const text = content ?? await ports.artifactContent(artifactId)
        triggerDownload(filenameOf(result, kind), text)
      } else {
        const fileUrl = result.fileUrl
        if (typeof fileUrl === 'string' && fileUrl) {
          window.open(fileUrl, '_blank', 'noopener')
        }
      }
    } finally {
      setDownloading(false)
    }
  }, [artifactId, content, ports, result, kind])

  const autoGenerated = result.autoGenerated === true
  const note = typeof result.note === 'string' ? result.note : null

  /** Send the generated artifact into the host EDA editor (HQ Edge only). */
  const place = useCallback(async (): Promise<void> => {
    if (placing || !ports.place || !artifactUri) return
    setPlacing(true)
    setPlaceStatus(null)
    try {
      await ports.place.placeArtifact({
        type: kind,
        artifactUri,
        ...(result.filename && typeof result.filename === 'string' ? { filename: result.filename } : {}),
      })
      setPlaceStatus(t('result.placeDone'))
    } catch (e) {
      setPlaceStatus(t('result.placeFailed') + String((e as Error)?.message || e))
    } finally {
      setPlacing(false)
    }
  }, [placing, ports, artifactUri, kind, result, t])

  const canPlace = !!ports.place?.canPlace(kind) && !!artifactUri

  return (
    <div className="cga-panel">
      <div className="cga-panel__body">
        {/* 返回 / 下载在左，上传的原图在右，同一行展示。 */}
        <div className="cga-result__bar">
          <div className="cga-result__bar-left">
            {leading ?? null}
            <button type="button" className="cga-btn cga-btn--primary" onClick={() => void download()} disabled={downloading}>
              {kind === 'symbol' ? t('symbol.download') : t('footprint.download')}
            </button>
          </div>
          {sourceImage
            ? (
              <div className="cga-source cga-source--inline">
                <span className="cga-source__label">{t('upload.sourceImage')}</span>
                <SourceImage src={sourceImage} t={t} />
              </div>
            )
            : null}
        </div>
        {autoGenerated ? <div className="cga-banner cga-banner--info">{t('footprint.directGenerated')}</div> : null}
        {content != null
          ? <PreviewStage kind={kind} content={content} srcKey={srcKey} t={t} />
          : previewErr
            ? <div className="cga-banner cga-banner--error">{t('app.error')}{previewErr}</div>
            : null}
        {note ? <div className="cga-banner cga-banner--info">{note}</div> : null}
        {canPlace
          ? (
            <div className="cga-actions">
              <button type="button" className="cga-btn" onClick={() => void place()} disabled={placing}>
                {placing ? t('result.placing') : t('result.place')}
              </button>
            </div>
          )
          : null}
        {placeStatus ? <div className="cga-banner cga-banner--info">{placeStatus}</div> : null}
      </div>
    </div>
  )
}
